head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[inputCalendar > P > dateValidSetCustom]<br/>dateValidSet=true 일때 유효하지 않은 날짜 또는 시간이 입력 되어도 복원하지 않도록 설정합니다.",
    "validation" : [        
        "유효하지 않은 날짜 또는 시간이 입력된 경우 별도의 처리나 팝업을 표시하려면 dateValidSet 속성을 true 설정하고 invalidMessageFunc 속성의 사용자 정의 함수에 처리하려는 코드를 정의하여야 합니다. ",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정   
    let properties = {
        editType : "select",        
        dateValidSet : true,        
        dateValidSetCustom : con_dateValidSetCustom.getText(),   
        invalidMessageFunc : "scwin.fn_invalidMessageFunc",
    };

    let cList = $c.gcm.createCList(properties);    
    let eList = $c.gcm.createEList(["onfocus"])   

    $c.gcm.createLabel('label="20251301 입력 후 포커스아웃 - 팝업 창 닫기 - 입력값 확인(이전 값 원복)"', '', 'label1');
    $c.gcm.createBasicInputCalendar(cList, eList);
}



scwin.btn_getValue_onclick = function (e) {
	let rtn = ''

    rtn = target1.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("입력값 : " + rtn);
};



scwin.fn_invalidMessageFunc = function() {
    let opts = {
        "id" : "popup1",
        "type" : "wframePopup",
        "width" : "440px",
        "height" : "90px",
        "top" : 100,
        "left" : 300,
        "popupName" : "date_validation_error",
        "modal" : true,
        "title" : "date validation error",
        "dataObject" : {
            "type" : "string",
            "data" : this.callerId,        // invalidMessageFunc를 호출한 컴포넌트의 id정보
            "name" : "callerId"
        }
    };

    if (!$p.getPopup("popup1")) {          // popup 중복 체크
        $p.openPopup("/sample/common_link/inputCalendar_P_dateValidSetCustom_popup.xml", opts);   // alert 대신 사용자 messagePopup을 띄운다
    }
};
